insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-dog-breeds-trivia',
  'Dog Breeds Trivia: Origins and Traits of Famous Breeds',
  'Eight questions on the origins and traits of famous dog breeds, from the Siberian Husky''s sledding past to the Basenji''s silent bark.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"Which breed was developed in Germany to hunt badgers, and is named after that prey?","options":[{"id":"a","text":"Beagle","is_correct":false},{"id":"b","text":"Dachshund","is_correct":true},{"id":"c","text":"Pembroke Welsh Corgi","is_correct":false},{"id":"d","text":"Basset Hound","is_correct":false}],"explanation":"Dachshund comes from the German Dachs (badger) and Hund (dog); its long body fit inside badger burrows."},{"id":"q2","question":"The Siberian Husky was bred by the Chukchi people of northeastern Asia mainly to do what?","options":[{"id":"a","text":"Herd reindeer","is_correct":false},{"id":"b","text":"Pull sleds over long distances","is_correct":true},{"id":"c","text":"Guard camps from bears","is_correct":false},{"id":"d","text":"Hunt seals on the ice","is_correct":false}],"explanation":"Chukchi teams pulled light loads across frozen Siberia; the breed reached Alaska in the early 1900s."},{"id":"q3","question":"Which African breed is known as the ''barkless dog'' because it yodels instead of barking?","options":[{"id":"a","text":"Basenji","is_correct":true},{"id":"b","text":"Rhodesian Ridgeback","is_correct":false},{"id":"c","text":"Pharaoh Hound","is_correct":false},{"id":"d","text":"Saluki","is_correct":false}],"explanation":"The Basenji of Central Africa has an unusually shaped larynx, so it makes a yodel-like sound called a barroo."},{"id":"q4","question":"Which Chinese breed is recognized by its lion-like mane and blue-black tongue?","options":[{"id":"a","text":"Shar-Pei","is_correct":false},{"id":"b","text":"Chow Chow","is_correct":true},{"id":"c","text":"Pug","is_correct":false},{"id":"d","text":"Pekingese","is_correct":false}],"explanation":"The Chow Chow is one of the oldest breeds and is famous for its dense ruff and distinctive dark tongue."},{"id":"q5","question":"Which herding breed from the Anglo-Scottish border is widely regarded as the most trainable working dog?","options":[{"id":"a","text":"German Shepherd","is_correct":false},{"id":"b","text":"Shetland Sheepdog","is_correct":false},{"id":"c","text":"Australian Shepherd","is_correct":false},{"id":"d","text":"Border Collie","is_correct":true}],"explanation":"The Border Collie was perfected by shepherds in the border country and excels at sheepdog trials and agility."},{"id":"q6","question":"The Dalmatian earned its place in firehouses by doing what historically?","options":[{"id":"a","text":"Pulling water carts","is_correct":false},{"id":"b","text":"Running alongside horse-drawn carriages as a coach dog","is_correct":true},{"id":"c","text":"Catching rats in stables","is_correct":false},{"id":"d","text":"Carrying messages between stations","is_correct":false}],"explanation":"Dalmatians ran ahead of and beside horse-drawn coaches; fire brigades kept the tradition with their engines."},{"id":"q7","question":"Which breed is the smallest dog recognized by major kennel clubs?","options":[{"id":"a","text":"Chihuahua","is_correct":true},{"id":"b","text":"Pomeranian","is_correct":false},{"id":"c","text":"Yorkshire Terrier","is_correct":false},{"id":"d","text":"Toy Poodle","is_correct":false}],"explanation":"The Chihuahua, named after the Mexican state, often weighs under two kilograms."},{"id":"q8","question":"The Labrador Retriever''s ancestors were developed to help fishermen in which region?","options":[{"id":"a","text":"Labrador, Canada","is_correct":false},{"id":"b","text":"Newfoundland, Canada","is_correct":true},{"id":"c","text":"Nova Scotia, Canada","is_correct":false},{"id":"d","text":"Scotland","is_correct":false}],"explanation":"Despite the name, the breed descends from the St. John''s water dog of Newfoundland; the standard was fixed in England."}]'::jsonb,
  null,
  array['animals', 'trivia', 'dogs', 'dog breeds']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-razas-de-perros',
  'Trivia de razas de perros: orígenes y rasgos',
  'Ocho preguntas sobre el origen y los rasgos de razas de perros famosas, del trineo del husky siberiano al basenji que no ladra.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"¿Qué raza se crió en Alemania para cazar tejones, de donde toma su nombre?","options":[{"id":"a","text":"Beagle","is_correct":false},{"id":"b","text":"Dachshund","is_correct":true},{"id":"c","text":"Corgi galés de Pembroke","is_correct":false},{"id":"d","text":"Basset hound","is_correct":false}],"explanation":"Dachshund viene del alemán Dachs (tejón) y Hund (perro); su cuerpo alargado cabía en las madrigueras."},{"id":"q2","question":"¿Para qué criaban los chukchi del noreste de Asia al husky siberiano?","options":[{"id":"a","text":"Para arrear renos","is_correct":false},{"id":"b","text":"Para tirar de trineos en largas distancias","is_correct":true},{"id":"c","text":"Para vigilar los campamentos frente a osos","is_correct":false},{"id":"d","text":"Para cazar focas en el hielo","is_correct":false}],"explanation":"Los equipos chukchi arrastraban cargas ligeras por Siberia; la raza llegó a Alaska a comienzos del siglo XX."},{"id":"q3","question":"¿Qué raza africana es conocida como «el perro que no ladra» porque emite un sonido parecido al yodel?","options":[{"id":"a","text":"Basenji","is_correct":true},{"id":"b","text":"Ridgeback de Rodesia","is_correct":false},{"id":"c","text":"Sabueso faraón","is_correct":false},{"id":"d","text":"Saluki","is_correct":false}],"explanation":"El basenji de África central tiene una laringe de forma inusual y produce un sonido llamado barroo."},{"id":"q4","question":"¿Qué raza china se reconoce por su melena de león y su lengua de color azul oscuro?","options":[{"id":"a","text":"Shar pei","is_correct":false},{"id":"b","text":"Chow chow","is_correct":true},{"id":"c","text":"Pug","is_correct":false},{"id":"d","text":"Pequinés","is_correct":false}],"explanation":"El chow chow es una de las razas más antiguas y destaca por su denso collar de pelo y su lengua oscura."},{"id":"q5","question":"¿Qué raza pastora de la frontera angloescocesa se considera el perro de trabajo más entrenable?","options":[{"id":"a","text":"Pastor alemán","is_correct":false},{"id":"b","text":"Pastor de las islas Shetland","is_correct":false},{"id":"c","text":"Pastor australiano","is_correct":false},{"id":"d","text":"Border collie","is_correct":true}],"explanation":"El border collie fue perfeccionado por pastores de la frontera y domina las pruebas de pastoreo y la agilidad."},{"id":"q6","question":"¿Qué hacía históricamente el dálmata para ganarse su lugar en los cuarteles de bomberos?","options":[{"id":"a","text":"Tirar de carros de agua","is_correct":false},{"id":"b","text":"Correr junto a los carruajes de caballos como perro de coche","is_correct":true},{"id":"c","text":"Cazar ratas en las cuadras","is_correct":false},{"id":"d","text":"Llevar mensajes entre estaciones","is_correct":false}],"explanation":"Los dálmatas corrían delante y al lado de los carruajes; los bomberos mantuvieron la tradición con sus carros."},{"id":"q7","question":"¿Cuál es la raza de perro más pequeña reconocida por las principales federaciones caninas?","options":[{"id":"a","text":"Chihuahua","is_correct":true},{"id":"b","text":"Pomerania","is_correct":false},{"id":"c","text":"Yorkshire terrier","is_correct":false},{"id":"d","text":"Caniche toy","is_correct":false}],"explanation":"El chihuahua, que toma el nombre del estado mexicano, suele pesar menos de dos kilos."},{"id":"q8","question":"¿En qué región se criaron los ancestros del labrador retriever para ayudar a los pescadores?","options":[{"id":"a","text":"Labrador, Canadá","is_correct":false},{"id":"b","text":"Terranova, Canadá","is_correct":true},{"id":"c","text":"Nueva Escocia, Canadá","is_correct":false},{"id":"d","text":"Escocia","is_correct":false}],"explanation":"A pesar del nombre, la raza desciende del perro de aguas de San Juan, de Terranova; el estándar se fijó en Inglaterra."}]'::jsonb,
  null,
  array['animales', 'trivia', 'perros', 'razas de perros']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-cat-breeds-trivia',
  'Cat Breeds Trivia: Origins of Famous Felines',
  'Eight questions on where famous cat breeds come from and what makes them unique, from the hairless Sphynx to the giant Maine Coon.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"Which breed is famous for its nearly hairless body, the result of a natural mutation in Canada?","options":[{"id":"a","text":"Sphynx","is_correct":true},{"id":"b","text":"Devon Rex","is_correct":false},{"id":"c","text":"Cornish Rex","is_correct":false},{"id":"d","text":"Burmese","is_correct":false}],"explanation":"The Sphynx emerged in Toronto in the 1960s from a natural genetic mutation and is bred for its hairless look."},{"id":"q2","question":"The Maine Coon, one of the largest domestic cat breeds, comes from which country?","options":[{"id":"a","text":"Norway","is_correct":false},{"id":"b","text":"United States","is_correct":true},{"id":"c","text":"Russia","is_correct":false},{"id":"d","text":"United Kingdom","is_correct":false}],"explanation":"The breed is native to the state of Maine, where its heavy coat and bushy tail suit the winters."},{"id":"q3","question":"Which breed, originally from Thailand, is famous for blue eyes and a color-pointed coat?","options":[{"id":"a","text":"Siamese","is_correct":true},{"id":"b","text":"Bombay","is_correct":false},{"id":"c","text":"Korat","is_correct":false},{"id":"d","text":"Russian Blue","is_correct":false}],"explanation":"The Siamese came from Siam, present-day Thailand; its darker points are caused by a temperature-sensitive enzyme."},{"id":"q4","question":"Which breed is defined by a natural mutation that folds its ears forward and down?","options":[{"id":"a","text":"Scottish Fold","is_correct":true},{"id":"b","text":"American Curl","is_correct":false},{"id":"c","text":"British Shorthair","is_correct":false},{"id":"d","text":"Devon Rex","is_correct":false}],"explanation":"The Scottish Fold''s ears bend forward; the American Curl''s ears curl backward instead."},{"id":"q5","question":"Which breed, native to Norway, has a dense water-resistant coat adapted to Scandinavian winters?","options":[{"id":"a","text":"Norwegian Forest Cat","is_correct":true},{"id":"b","text":"Russian Blue","is_correct":false},{"id":"c","text":"Chartreux","is_correct":false},{"id":"d","text":"British Shorthair","is_correct":false}],"explanation":"The Norwegian Forest Cat, or skogkatt, has a double coat and tufted paws built for snowy forests."},{"id":"q6","question":"Which short-tailed Japanese breed is said to have inspired the maneki-neko ''beckoning cat'' figurine?","options":[{"id":"a","text":"Japanese Bobtail","is_correct":true},{"id":"b","text":"Manx","is_correct":false},{"id":"c","text":"Korat","is_correct":false},{"id":"d","text":"Birman","is_correct":false}],"explanation":"The Japanese Bobtail''s pom-pom tail has appeared in art for centuries, and the lucky cat is modeled on it."},{"id":"q7","question":"Which breed was created by crossing domestic cats with the Asian leopard cat (Prionailurus bengalensis)?","options":[{"id":"a","text":"Bengal","is_correct":true},{"id":"b","text":"Savannah","is_correct":false},{"id":"c","text":"Ocicat","is_correct":false},{"id":"d","text":"Egyptian Mau","is_correct":false}],"explanation":"The Bengal pairs domestic cats with the Asian leopard cat; the Ocicat looks wild but has no wildcat blood."},{"id":"q8","question":"Which breed was named for its tendency to go limp and relaxed when picked up?","options":[{"id":"a","text":"Ragdoll","is_correct":true},{"id":"b","text":"Persian","is_correct":false},{"id":"c","text":"Birman","is_correct":false},{"id":"d","text":"Himalayan","is_correct":false}],"explanation":"The Ragdoll was developed in California in the 1960s and is famous for its placid, floppy temperament."}]'::jsonb,
  null,
  array['animals', 'trivia', 'cats', 'cat breeds']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-razas-de-gatos',
  'Trivia de razas de gatos: orígenes y rasgos felinos',
  'Ocho preguntas sobre el origen y los rasgos de razas de gatos famosas, del gato esfinge sin pelo al gigante Maine Coon.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"¿Qué raza es famosa por su cuerpo casi sin pelo, resultado de una mutación natural en Canadá?","options":[{"id":"a","text":"Esfinge o sphynx","is_correct":true},{"id":"b","text":"Devon rex","is_correct":false},{"id":"c","text":"Cornish rex","is_correct":false},{"id":"d","text":"Bosque de Noruega","is_correct":false}],"explanation":"El sphynx surgió en Toronto en los años sesenta por una mutación genética natural y se cría por su aspecto sin pelo."},{"id":"q2","question":"¿De qué país procede el Maine Coon, una de las razas de gato doméstico más grandes?","options":[{"id":"a","text":"Noruega","is_correct":false},{"id":"b","text":"Estados Unidos","is_correct":true},{"id":"c","text":"Rusia","is_correct":false},{"id":"d","text":"Reino Unido","is_correct":false}],"explanation":"La raza es originaria del estado de Maine, donde su pelaje espeso y su cola poblada resisten el invierno."},{"id":"q3","question":"¿Qué raza, originaria de Tailandia, es famosa por sus ojos azules y su manto de extremidades oscuras?","options":[{"id":"a","text":"Siamés","is_correct":true},{"id":"b","text":"Bombay","is_correct":false},{"id":"c","text":"Korat","is_correct":false},{"id":"d","text":"Azul ruso","is_correct":false}],"explanation":"El siamés procede del antiguo Siam, la actual Tailandia; sus puntas oscuras se deben a una enzima sensible a la temperatura."},{"id":"q4","question":"¿Qué raza se define por una mutación natural que dobla las orejas hacia adelante y abajo?","options":[{"id":"a","text":"Scottish fold","is_correct":true},{"id":"b","text":"American curl","is_correct":false},{"id":"c","text":"British shorthair","is_correct":false},{"id":"d","text":"Devon rex","is_correct":false}],"explanation":"Las orejas del scottish fold se doblan hacia adelante; las del american curl se curvan hacia atrás."},{"id":"q5","question":"¿Qué raza, originaria de Noruega, tiene un manto denso e impermeable adaptado a los inviernos escandinavos?","options":[{"id":"a","text":"Bosque de Noruega","is_correct":true},{"id":"b","text":"Azul ruso","is_correct":false},{"id":"c","text":"Cartujo","is_correct":false},{"id":"d","text":"British shorthair","is_correct":false}],"explanation":"El gato bosque de Noruega, o skogkatt, tiene doble capa de pelo y patas con mechones para el bosque nevado."},{"id":"q6","question":"¿Qué raza japonesa de cola corta inspiró la figura del maneki-neko, el «gato de la suerte»?","options":[{"id":"a","text":"Bobtail japonés","is_correct":true},{"id":"b","text":"Manx","is_correct":false},{"id":"c","text":"Korat","is_correct":false},{"id":"d","text":"Sagrado de Birmania","is_correct":false}],"explanation":"La cola en pompón del bobtail japonés aparece en el arte desde hace siglos y el gato de la fortuna se modeló sobre ella."},{"id":"q7","question":"¿Qué raza se creó cruzando gatos domésticos con el gato leopardo asiático (Prionailurus bengalensis)?","options":[{"id":"a","text":"Bengalí","is_correct":true},{"id":"b","text":"Savannah","is_correct":false},{"id":"c","text":"Ocicat","is_correct":false},{"id":"d","text":"Mau egipcio","is_correct":false}],"explanation":"El bengalí combina gatos domésticos con el gato leopardo asiático; el ocicat parece salvaje pero no tiene sangre de felino silvestre."},{"id":"q8","question":"¿Qué raza debe su nombre a que se relaja y queda floja cuando la toman en brazos?","options":[{"id":"a","text":"Ragdoll","is_correct":true},{"id":"b","text":"Persa","is_correct":false},{"id":"c","text":"Sagrado de Birmania","is_correct":false},{"id":"d","text":"Himalayo","is_correct":false}],"explanation":"El ragdoll se creó en California en los años sesenta y es famoso por su temperamento tranquilo y relajado."}]'::jsonb,
  null,
  array['animales', 'trivia', 'gatos', 'razas de gatos']::text[],
  3,
  'published',
  false,
  false,
  now()
)
