insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-birds-trivia',
  'Birds Trivia: Record Holders and Remarkable Species',
  'Eight questions on the most remarkable birds on Earth: the biggest, the fastest and the farthest-flying species and how they do it.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"Which bird has the largest wingspan of any living species, reaching about 3.5 metres?","options":[{"id":"a","text":"Wandering albatross","is_correct":true},{"id":"b","text":"Andean condor","is_correct":false},{"id":"c","text":"Mute swan","is_correct":false},{"id":"d","text":"Golden eagle","is_correct":false}],"explanation":"The wandering albatross (Diomedea exulans) holds the record, with verified wingspans of over 3.4 metres."},{"id":"q2","question":"Which is the largest living bird, native to Africa and unable to fly?","options":[{"id":"a","text":"Emu","is_correct":false},{"id":"b","text":"Southern cassowary","is_correct":false},{"id":"c","text":"Common ostrich","is_correct":true},{"id":"d","text":"Emperor penguin","is_correct":false}],"explanation":"The common ostrich (Struthio camelus) stands up to 2.8 metres tall and can weigh over 150 kilograms."},{"id":"q3","question":"Which bird is the fastest animal on Earth in a hunting dive, exceeding 300 km/h?","options":[{"id":"a","text":"Golden eagle","is_correct":false},{"id":"b","text":"Peregrine falcon","is_correct":true},{"id":"c","text":"Common swift","is_correct":false},{"id":"d","text":"Gyrfalcon","is_correct":false}],"explanation":"The peregrine falcon (Falco peregrinus) has been measured above 320 km/h in a stoop."},{"id":"q4","question":"Which small bird can stay airborne for around ten months, feeding, drinking and even sleeping on the wing?","options":[{"id":"a","text":"Barn swallow","is_correct":false},{"id":"b","text":"Common swift","is_correct":true},{"id":"c","text":"House martin","is_correct":false},{"id":"d","text":"Arctic tern","is_correct":false}],"explanation":"Tracking studies show the common swift (Apus apus) lands only to breed."},{"id":"q5","question":"Which seabird makes the longest migration on Earth, flying between the Arctic and Antarctic each year?","options":[{"id":"a","text":"Arctic tern","is_correct":true},{"id":"b","text":"Bar-tailed godwit","is_correct":false},{"id":"c","text":"Wandering albatross","is_correct":false},{"id":"d","text":"Northern gannet","is_correct":false}],"explanation":"The Arctic tern (Sterna paradisaea) can cover more than 70,000 kilometres a year between the poles."},{"id":"q6","question":"Which bird can hover in place and is the only group able to fly backwards?","options":[{"id":"a","text":"Kestrel","is_correct":false},{"id":"b","text":"Kingfisher","is_correct":false},{"id":"c","text":"Hummingbird","is_correct":true},{"id":"d","text":"Sunbird","is_correct":false}],"explanation":"Hummingbirds beat their wings in a figure-eight pattern, which allows hovering and backward flight."},{"id":"q7","question":"Which Andean scavenger is among the largest flying birds, with a wingspan over three metres?","options":[{"id":"a","text":"Harpy eagle","is_correct":false},{"id":"b","text":"California condor","is_correct":false},{"id":"c","text":"Cinereous vulture","is_correct":false},{"id":"d","text":"Andean condor","is_correct":true}],"explanation":"The Andean condor (Vultur gryphus) soars on mountain thermals and can weigh up to 15 kilograms."},{"id":"q8","question":"Which flightless New Zealand bird lays an egg equal to about a quarter of its body weight?","options":[{"id":"a","text":"Kiwi","is_correct":true},{"id":"b","text":"Kakapo","is_correct":false},{"id":"c","text":"Weka","is_correct":false},{"id":"d","text":"Southern cassowary","is_correct":false}],"explanation":"The kiwi''s egg is the largest relative to body size of any bird, so the female needs an unusually wide pelvis."}]'::jsonb,
  null,
  array['animals', 'trivia', 'birds', 'nature']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-aves',
  'Trivia de aves: récords y especies extraordinarias',
  'Ocho preguntas sobre las aves más extraordinarias del planeta: las más grandes, las más rápidas y las que vuelan más lejos.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"¿Qué ave tiene la mayor envergadura de todas las especies vivas, de unos 3,5 metros?","options":[{"id":"a","text":"Albatros errante","is_correct":true},{"id":"b","text":"Cóndor andino","is_correct":false},{"id":"c","text":"Cisne blanco","is_correct":false},{"id":"d","text":"Águila real","is_correct":false}],"explanation":"El albatros errante (Diomedea exulans) ostenta el récord, con envergaduras verificadas de más de 3,4 metros."},{"id":"q2","question":"¿Cuál es el ave viva más grande, originaria de África e incapaz de volar?","options":[{"id":"a","text":"Emú","is_correct":false},{"id":"b","text":"Casuario austral","is_correct":false},{"id":"c","text":"Avestruz común","is_correct":true},{"id":"d","text":"Pingüino emperador","is_correct":false}],"explanation":"El avestruz común (Struthio camelus) mide hasta 2,8 metros y puede superar los 150 kilos."},{"id":"q3","question":"¿Qué ave es el animal más rápido del planeta en picado de caza, superando los 300 km/h?","options":[{"id":"a","text":"Águila real","is_correct":false},{"id":"b","text":"Halcón peregrino","is_correct":true},{"id":"c","text":"Vencejo común","is_correct":false},{"id":"d","text":"Halcón gerifalte","is_correct":false}],"explanation":"El halcón peregrino (Falco peregrinus) se ha medido por encima de los 320 km/h en picado."},{"id":"q4","question":"¿Qué ave pequeña puede permanecer en el aire unos diez meses, comiendo, bebiendo e incluso durmiendo en vuelo?","options":[{"id":"a","text":"Golondrina común","is_correct":false},{"id":"b","text":"Vencejo común","is_correct":true},{"id":"c","text":"Avión común","is_correct":false},{"id":"d","text":"Charrán ártico","is_correct":false}],"explanation":"Los estudios de seguimiento muestran que el vencejo común (Apus apus) solo se posa para criar."},{"id":"q5","question":"¿Qué ave marina realiza la migración más larga de la Tierra, volando cada año entre el Ártico y la Antártida?","options":[{"id":"a","text":"Charrán ártico","is_correct":true},{"id":"b","text":"Aguja colipinta","is_correct":false},{"id":"c","text":"Albatros errante","is_correct":false},{"id":"d","text":"Alcatraz común","is_correct":false}],"explanation":"El charrán ártico (Sterna paradisaea) puede recorrer más de 70.000 kilómetros al año entre los polos."},{"id":"q6","question":"¿Qué ave puede volar suspendida en un punto y es el único grupo capaz de volar hacia atrás?","options":[{"id":"a","text":"Cernícalo","is_correct":false},{"id":"b","text":"Martín pescador","is_correct":false},{"id":"c","text":"Colibrí","is_correct":true},{"id":"d","text":"Suimanga","is_correct":false}],"explanation":"Los colibríes baten las alas en forma de ocho, lo que permite el vuelo sostenido y hacia atrás."},{"id":"q7","question":"¿Qué ave carroñera de los Andes está entre las aves voladoras más grandes, con más de tres metros de envergadura?","options":[{"id":"a","text":"Águila harpía","is_correct":false},{"id":"b","text":"Cóndor de California","is_correct":false},{"id":"c","text":"Buitre negro","is_correct":false},{"id":"d","text":"Cóndor andino","is_correct":true}],"explanation":"El cóndor andino (Vultur gryphus) planea en las corrientes térmicas y puede pesar hasta 15 kilos."},{"id":"q8","question":"¿Qué ave no voladora de Nueva Zelanda pone un huevo equivalente a un cuarto de su peso corporal?","options":[{"id":"a","text":"Kiwi","is_correct":true},{"id":"b","text":"Kákapo","is_correct":false},{"id":"c","text":"Weka","is_correct":false},{"id":"d","text":"Casuario austral","is_correct":false}],"explanation":"El huevo del kiwi es el mayor en proporción al cuerpo de todas las aves; la hembra necesita una pelvis muy ancha."}]'::jsonb,
  null,
  array['animales', 'trivia', 'aves', 'naturaleza']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-big-cats-trivia',
  'Big Cats Trivia: Lions, Tigers and Other Great Felines',
  'Eight questions on the great cats of the world: where they live, how they hunt and what sets lions, tigers, leopards and jaguars apart.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"Which big cat is the only one that lives in social groups called prides?","options":[{"id":"a","text":"Lion","is_correct":true},{"id":"b","text":"Tiger","is_correct":false},{"id":"c","text":"Leopard","is_correct":false},{"id":"d","text":"Cheetah","is_correct":false}],"explanation":"Lions form prides of related females with their cubs and a small group of males; the others live mainly alone."},{"id":"q2","question":"Which is the largest living cat species, with males that can exceed 300 kilograms?","options":[{"id":"a","text":"Lion","is_correct":false},{"id":"b","text":"Jaguar","is_correct":false},{"id":"c","text":"Tiger","is_correct":true},{"id":"d","text":"Leopard","is_correct":false}],"explanation":"The tiger (Panthera tigris) is the biggest cat; the largest males of the Siberian and Bengal populations top 300 kg."},{"id":"q3","question":"Which big cat habitually hauls its prey into trees, out of reach of scavengers?","options":[{"id":"a","text":"Cheetah","is_correct":false},{"id":"b","text":"Lion","is_correct":false},{"id":"c","text":"Leopard","is_correct":true},{"id":"d","text":"Puma","is_correct":false}],"explanation":"The leopard can climb while carrying prey heavier than itself, keeping kills away from hyenas and lions."},{"id":"q4","question":"The ''black panthers'' of the Americas are usually melanistic individuals of which species?","options":[{"id":"a","text":"Puma","is_correct":false},{"id":"b","text":"Ocelot","is_correct":false},{"id":"c","text":"Leopard","is_correct":false},{"id":"d","text":"Jaguar","is_correct":true}],"explanation":"In the Americas a black panther is almost always a melanistic jaguar; in Asia and Africa the term refers to leopards."},{"id":"q5","question":"Which cat has the widest natural range in the Americas, from Canada to the southern Andes?","options":[{"id":"a","text":"Jaguar","is_correct":false},{"id":"b","text":"Ocelot","is_correct":false},{"id":"c","text":"Bobcat","is_correct":false},{"id":"d","text":"Puma","is_correct":true}],"explanation":"The puma (Puma concolor), also called cougar or mountain lion, ranges farther than any other land mammal in the hemisphere."},{"id":"q6","question":"Which big cat is adapted to the high mountains of Central and South Asia, with a thick smoky-grey coat?","options":[{"id":"a","text":"Clouded leopard","is_correct":false},{"id":"b","text":"Snow leopard","is_correct":true},{"id":"c","text":"Eurasian lynx","is_correct":false},{"id":"d","text":"Bengal tiger","is_correct":false}],"explanation":"The snow leopard (Panthera uncia) lives between roughly 3,000 and 5,500 metres in the Himalayas and neighbouring ranges."},{"id":"q7","question":"Which cat is the fastest land animal, though it is not a member of the genus Panthera?","options":[{"id":"a","text":"Cheetah","is_correct":true},{"id":"b","text":"Lion","is_correct":false},{"id":"c","text":"Leopard","is_correct":false},{"id":"d","text":"Tiger","is_correct":false}],"explanation":"The cheetah (Acinonyx jubatus) reaches around 100 km/h in short bursts and cannot roar like the Panthera cats."},{"id":"q8","question":"Which forest cat of Southeast Asia has the longest canine teeth relative to body size?","options":[{"id":"a","text":"Serval","is_correct":false},{"id":"b","text":"Caracal","is_correct":false},{"id":"c","text":"Clouded leopard","is_correct":true},{"id":"d","text":"Fishing cat","is_correct":false}],"explanation":"The clouded leopard (Neofelis nebulosa) has canines proportionally as long as those of some extinct sabre-tooths."}]'::jsonb,
  null,
  array['animals', 'trivia', 'big cats', 'felines']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-grandes-felinos',
  'Trivia de grandes felinos: leones, tigres y otros depredadores',
  'Ocho preguntas sobre los grandes felinos del mundo: dónde viven, cómo cazan y qué distingue a leones, tigres, leopardos y jaguares.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"¿Qué gran felino es el único que vive en grupos sociales llamados manadas?","options":[{"id":"a","text":"León","is_correct":true},{"id":"b","text":"Tigre","is_correct":false},{"id":"c","text":"Leopardo","is_correct":false},{"id":"d","text":"Guepardo","is_correct":false}],"explanation":"Los leones forman manadas de hembras emparentadas con sus cachorros y pocos machos; los demás viven casi siempre solos."},{"id":"q2","question":"¿Cuál es la especie de felino viva más grande, con machos que pueden superar los 300 kilos?","options":[{"id":"a","text":"León","is_correct":false},{"id":"b","text":"Jaguar","is_correct":false},{"id":"c","text":"Tigre","is_correct":true},{"id":"d","text":"Leopardo","is_correct":false}],"explanation":"El tigre (Panthera tigris) es el felino más grande; los machos de las poblaciones siberiana y bengalí superan los 300 kilos."},{"id":"q3","question":"¿Qué gran felino sube sus presas a los árboles para alejarlas de los carroñeros?","options":[{"id":"a","text":"Guepardo","is_correct":false},{"id":"b","text":"León","is_correct":false},{"id":"c","text":"Leopardo","is_correct":true},{"id":"d","text":"Puma","is_correct":false}],"explanation":"El leopardo puede trepar cargando presas más pesadas que él para resguardarlas de hienas y leones."},{"id":"q4","question":"Las «panteras negras» de América suelen ser ejemplares melánicos de qué especie?","options":[{"id":"a","text":"Puma","is_correct":false},{"id":"b","text":"Ocelote","is_correct":false},{"id":"c","text":"Leopardo","is_correct":false},{"id":"d","text":"Jaguar","is_correct":true}],"explanation":"En América una pantera negra es casi siempre un jaguar melánico; en Asia y África el término se refiere a leopardos."},{"id":"q5","question":"¿Qué felino tiene la mayor distribución natural de América, desde Canadá hasta los Andes del sur?","options":[{"id":"a","text":"Jaguar","is_correct":false},{"id":"b","text":"Ocelote","is_correct":false},{"id":"c","text":"Lince rojo","is_correct":false},{"id":"d","text":"Puma","is_correct":true}],"explanation":"El puma (Puma concolor), también llamado león de montaña, abarca más territorio que cualquier otro mamífero terrestre del hemisferio."},{"id":"q6","question":"¿Qué gran felino está adaptado a las altas montañas de Asia central y meridional, con un pelaje grisáceo y espeso?","options":[{"id":"a","text":"Pantera nebulosa","is_correct":false},{"id":"b","text":"Leopardo de las nieves","is_correct":true},{"id":"c","text":"Lince euroasiático","is_correct":false},{"id":"d","text":"Tigre de Bengala","is_correct":false}],"explanation":"El leopardo de las nieves (Panthera uncia) vive entre unos 3.000 y 5.500 metros en el Himalaya y cordilleras vecinas."},{"id":"q7","question":"¿Qué felino es el animal terrestre más rápido, aunque no pertenece al género Panthera?","options":[{"id":"a","text":"Guepardo","is_correct":true},{"id":"b","text":"León","is_correct":false},{"id":"c","text":"Leopardo","is_correct":false},{"id":"d","text":"Tigre","is_correct":false}],"explanation":"El guepardo (Acinonyx jubatus) alcanza unos 100 km/h en carreras cortas y no puede rugir como los Panthera."},{"id":"q8","question":"¿Qué felino de los bosques del sudeste asiático tiene los caninos más largos en proporción a su tamaño?","options":[{"id":"a","text":"Serval","is_correct":false},{"id":"b","text":"Caracal","is_correct":false},{"id":"c","text":"Pantera nebulosa","is_correct":true},{"id":"d","text":"Gato pescador","is_correct":false}],"explanation":"La pantera nebulosa (Neofelis nebulosa) tiene unos caninos tan largos, en proporción, como los de algunos dientes de sable extintos."}]'::jsonb,
  null,
  array['animales', 'trivia', 'grandes felinos', 'felinos']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-venomous-animals-trivia',
  'Venomous Animals Trivia: Snakes, Spiders and Sea Creatures',
  'Eight questions on venomous animals around the world, from the inland taipan and the blue-ringed octopus to the surprising platypus.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"Which Australian snake has the most toxic venom of any land snake measured?","options":[{"id":"a","text":"King cobra","is_correct":false},{"id":"b","text":"Black mamba","is_correct":false},{"id":"c","text":"Inland taipan","is_correct":true},{"id":"d","text":"Eastern brown snake","is_correct":false}],"explanation":"The inland taipan (Oxyuranus microlepidotus) tops toxicity tests; it lives in remote areas and bites are extremely rare."},{"id":"q2","question":"Which is the world''s longest venomous snake, reaching over five metres?","options":[{"id":"a","text":"King cobra","is_correct":true},{"id":"b","text":"Black mamba","is_correct":false},{"id":"c","text":"Gaboon viper","is_correct":false},{"id":"d","text":"Boa constrictor","is_correct":false}],"explanation":"The king cobra (Ophiophagus hannah) of South and Southeast Asia feeds mainly on other snakes."},{"id":"q3","question":"Which small octopus flashes bright blue rings when threatened and carries lethal tetrodotoxin?","options":[{"id":"a","text":"Mimic octopus","is_correct":false},{"id":"b","text":"Blue-ringed octopus","is_correct":true},{"id":"c","text":"Common octopus","is_correct":false},{"id":"d","text":"Dumbo octopus","is_correct":false}],"explanation":"The blue-ringed octopus (Hapalochlaena) of Australian waters carries enough toxin to kill several adults."},{"id":"q4","question":"Which jellyfish, found in northern Australian waters, is considered the most venomous marine animal?","options":[{"id":"a","text":"Lion''s mane jellyfish","is_correct":false},{"id":"b","text":"Portuguese man o'' war","is_correct":false},{"id":"c","text":"Irukandji jellyfish","is_correct":false},{"id":"d","text":"Australian box jellyfish","is_correct":true}],"explanation":"Chironex fleckeri, the Australian box jellyfish or sea wasp, has tentacles that can kill within minutes."},{"id":"q5","question":"Which mammal injects venom through spurs on its hind legs, one of the very few venomous mammals?","options":[{"id":"a","text":"Slow loris","is_correct":false},{"id":"b","text":"Echidna","is_correct":false},{"id":"c","text":"Platypus","is_correct":true},{"id":"d","text":"Hispaniolan solenodon","is_correct":false}],"explanation":"Male platypuses carry venomous ankle spurs that deliver intense pain; the venom flows in the breeding season."},{"id":"q6","question":"Which venomous lizard with black-and-orange beaded skin lives in the southwestern United States and Mexico?","options":[{"id":"a","text":"Gila monster","is_correct":true},{"id":"b","text":"Mexican beaded lizard","is_correct":false},{"id":"c","text":"Green iguana","is_correct":false},{"id":"d","text":"Thorny devil","is_correct":false}],"explanation":"The Gila monster (Heloderma suspectum) chews venom into its victim and is protected by law in several US states."},{"id":"q7","question":"Which spider is known for necrotic venom and a violin-shaped mark on its back?","options":[{"id":"a","text":"Black widow","is_correct":false},{"id":"b","text":"Sydney funnel-web","is_correct":false},{"id":"c","text":"Brown recluse","is_correct":true},{"id":"d","text":"Wolf spider","is_correct":false}],"explanation":"The brown recluse (Loxosceles reclusa) of the United States carries a violin-shaped mark pointing toward the abdomen."},{"id":"q8","question":"Which fish, camouflaged on tropical reefs, has the most venomous spines of any fish?","options":[{"id":"a","text":"Lionfish","is_correct":false},{"id":"b","text":"Stonefish","is_correct":true},{"id":"c","text":"Pufferfish","is_correct":false},{"id":"d","text":"Moray eel","is_correct":false}],"explanation":"The stonefish (Synanceia) hides like a rock and its dorsal spines inject one of the most painful venoms known."}]'::jsonb,
  null,
  array['animals', 'trivia', 'venomous animals', 'snakes']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-animales-venenosos',
  'Trivia de animales venenosos: serpientes, arañas y vida marina',
  'Ocho preguntas sobre animales venenosos del mundo, de la taipán del interior y el pulpo de anillos azules al sorprendente ornitorrinco.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"¿Qué serpiente australiana tiene el veneno más tóxico de todas las serpientes terrestres medidas?","options":[{"id":"a","text":"Cobra real","is_correct":false},{"id":"b","text":"Mamba negra","is_correct":false},{"id":"c","text":"Taipán del interior","is_correct":true},{"id":"d","text":"Serpiente marrón oriental","is_correct":false}],"explanation":"La taipán del interior (Oxyuranus microlepidotus) encabeza las pruebas de toxicidad; vive en zonas remotas y las mordeduras son rarísimas."},{"id":"q2","question":"¿Cuál es la serpiente venenosa más larga del mundo, capaz de superar los cinco metros?","options":[{"id":"a","text":"Cobra real","is_correct":true},{"id":"b","text":"Mamba negra","is_correct":false},{"id":"c","text":"Víbora de Gabón","is_correct":false},{"id":"d","text":"Boa constrictor","is_correct":false}],"explanation":"La cobra real (Ophiophagus hannah), del sur y sudeste asiático, se alimenta sobre todo de otras serpientes."},{"id":"q3","question":"¿Qué pequeño pulpo muestra brillantes anillos azules al sentirse amenazado y porta tetrodotoxina letal?","options":[{"id":"a","text":"Pulpo mímico","is_correct":false},{"id":"b","text":"Pulpo de anillos azules","is_correct":true},{"id":"c","text":"Pulpo común","is_correct":false},{"id":"d","text":"Pulpo dumbo","is_correct":false}],"explanation":"El pulpo de anillos azules (Hapalochlaena), de aguas australianas, porta toxina suficiente para matar a varios adultos."},{"id":"q4","question":"¿Qué medusa, presente en las aguas del norte de Australia, se considera el animal marino más venenoso?","options":[{"id":"a","text":"Medusa melena de león","is_correct":false},{"id":"b","text":"Carabela portuguesa","is_correct":false},{"id":"c","text":"Medusa irukandji","is_correct":false},{"id":"d","text":"Avispa de mar australiana","is_correct":true}],"explanation":"Chironex fleckeri, la avispa de mar o medusa de caja australiana, tiene tentáculos capaces de matar en minutos."},{"id":"q5","question":"¿Qué mamífero inyecta veneno con espolones en las patas traseras, uno de los poquísimos mamíferos venenosos?","options":[{"id":"a","text":"Loris perezoso","is_correct":false},{"id":"b","text":"Equidna","is_correct":false},{"id":"c","text":"Ornitorrinco","is_correct":true},{"id":"d","text":"Solenodonte de La Española","is_correct":false}],"explanation":"Los ornitorrincos macho llevan espolones venenosos en el tobillo; el veneno fluye en la época de cría."},{"id":"q6","question":"¿Qué lagarto venenoso de piel negra y naranja con aspecto de cuentas vive en el suroeste de Estados Unidos y México?","options":[{"id":"a","text":"Monstruo de Gila","is_correct":true},{"id":"b","text":"Lagarto enchaquirado mexicano","is_correct":false},{"id":"c","text":"Iguana verde","is_correct":false},{"id":"d","text":"Diablo espinoso","is_correct":false}],"explanation":"El monstruo de Gila (Heloderma suspectum) inocula el veneno masticando; está protegido por ley en varios estados de EE. UU."},{"id":"q7","question":"¿Qué araña se reconoce por su veneno necrótico y una marca en forma de violín en el dorso?","options":[{"id":"a","text":"Viuda negra","is_correct":false},{"id":"b","text":"Araña de tela embudo de Sídney","is_correct":false},{"id":"c","text":"Reclusa parda","is_correct":true},{"id":"d","text":"Araña lobo","is_correct":false}],"explanation":"La reclusa parda (Loxosceles reclusa), de Estados Unidos, lleva una marca de violín que apunta hacia el abdomen."},{"id":"q8","question":"¿Qué pez, camuflado en los arrecifes tropicales, tiene las espinas más venenosas de todos los peces?","options":[{"id":"a","text":"Pez león","is_correct":false},{"id":"b","text":"Pez piedra","is_correct":true},{"id":"c","text":"Pez globo","is_correct":false},{"id":"d","text":"Morena","is_correct":false}],"explanation":"El pez piedra (Synanceia) se oculta como una roca y sus espinas dorsales inyectan uno de los venenos más dolorosos que existen."}]'::jsonb,
  null,
  array['animales', 'trivia', 'animales venenosos', 'serpientes']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

